-- 003 T017 · FR-010–014/056/063: «misma clave y misma huella devuelve el mismo resultado»; R1 row_count.
begin;
select no_plan();
select tests.create_user('11111111-1111-4111-8111-111111111111','sara@seed.test');
select tests.create_user('22222222-2222-4222-8222-222222222222','tomas@seed.test');
select tests.create_user('33333333-3333-4333-8333-333333333333','carla@seed.test');
select tests.create_user('44444444-4444-4444-8444-444444444444','diana@seed.test');
insert into juntia_data.profiles(user_id,display_name) values
 ('11111111-1111-4111-8111-111111111111','Sara'),('22222222-2222-4222-8222-222222222222','Tomás'),
 ('33333333-3333-4333-8333-333333333333','Carla'),('44444444-4444-4444-8444-444444444444','Diana');
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated","email":"diana@seed.test"}';
select throws_ok($$select public.create_invitation(gen_random_uuid()::text,' diana@seed.test ',repeat('a',64))$$,'JT108',null,'no invita al propio correo');
select throws_ok(format('select public.create_invitation(gen_random_uuid()::text,%L,repeat(''a'',64))',email),'JT108',null,'correo inválido '||coalesce(email,'null')) from unnest(array['','bad','a b@c.test',null]) email;
select throws_ok(format('select public.create_invitation(gen_random_uuid()::text,''tomas@seed.test'',%L)',hash),'JT109',null,'hash inválido '||coalesce(hash,'null')) from unnest(array['abc',repeat('A',64),repeat('a',63),null]) hash;
set local "request.jwt.claims" = '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","email":"sara@seed.test"}';
select set_config('tests.invitation',public.create_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',' TOMAS@SEED.TEST ',repeat('a',64))::text,true);
select is(public.create_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','tomas@seed.test',repeat('a',64)),current_setting('tests.invitation')::jsonb,'crear idempotente y correo normalizado');
select throws_ok($$select public.create_invitation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','tomas@seed.test',repeat('b',64))$$,'JT008',null,'misma clave con hash distinto falla');
select throws_ok($$select public.create_invitation(gen_random_uuid()::text,'carla@seed.test',repeat('d',64))$$,'JT101',null,'una pareja provisional por persona');
reset role;
select is((select token_hash from juntia_data.group_invitations where id=(current_setting('tests.invitation')::jsonb->>'invitation_id')::uuid),repeat('a',64),'solo hash guardado');
select is((select expires_at-created_at from juntia_data.group_invitations where id=(current_setting('tests.invitation')::jsonb->>'invitation_id')::uuid),interval '7 days','caduca en siete días');
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated","email":"tomas@seed.test"}';
select is(public.preview_invitation(repeat('a',64))->>'inviter_display_name','Sara','preview de la cuenta invitada');
select is((select array_agg(k order by k) from jsonb_object_keys(public.preview_invitation(repeat('a',64))) k),array['expires_at','inviter_display_name'],'preview solo nombre y caducidad');
set local "request.jwt.claims" = '{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","email":"carla@seed.test"}';
select throws_ok($$select public.preview_invitation(repeat('a',64))$$,'JT104',null,'preview ajeno no enumera');
select throws_ok($$select public.accept_invitation(gen_random_uuid()::text,repeat('a',64))$$,'JT104',null,'tercero no acepta');
select throws_ok(format('select public.cancel_invitation(gen_random_uuid()::text,%L::uuid,1)',current_setting('tests.invitation')::jsonb->>'group_id'),'JT102',null,'tercero no anula');
select throws_ok(format('select public.regenerate_invitation(gen_random_uuid()::text,%L::uuid,1,repeat(''b'',64))',current_setting('tests.invitation')::jsonb->>'group_id'),'JT102',null,'tercero no regenera');
set local "request.jwt.claims" = '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","email":"sara@seed.test"}';
select set_config('tests.regenerated',public.regenerate_invitation('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',(current_setting('tests.invitation')::jsonb->>'group_id')::uuid,1,repeat('b',64))::text,true);
select is(current_setting('tests.regenerated')::jsonb->>'version','2','regenerar sube groups.version');
select is(public.regenerate_invitation('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',(current_setting('tests.invitation')::jsonb->>'group_id')::uuid,1,repeat('b',64)),current_setting('tests.regenerated')::jsonb,'regenerar idempotente antes de versión');
select throws_ok(format('select public.regenerate_invitation(gen_random_uuid()::text,%L::uuid,1,repeat(''c'',64))',current_setting('tests.invitation')::jsonb->>'group_id'),'JT011',null,'segunda regeneración con versión antigua no reemplaza');
select throws_ok(format('select public.regenerate_invitation(''bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'',%L::uuid,1,repeat(''c'',64))',current_setting('tests.invitation')::jsonb->>'group_id'),'JT008',null,'regenerar con otra huella');
set local "request.jwt.claims" = '{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated","email":"tomas@seed.test"}';
select throws_ok($$select public.preview_invitation(repeat('a',64))$$,'JT104',null,'enlace reemplazado ya no sirve');
select set_config('tests.accepted',public.accept_invitation('cccccccc-cccc-4ccc-8ccc-cccccccccccc',repeat('b',64))::text,true);
select is(current_setting('tests.accepted')::jsonb->>'status','active','aceptar activa la pareja');
select is(public.accept_invitation('cccccccc-cccc-4ccc-8ccc-cccccccccccc',repeat('b',64)),current_setting('tests.accepted')::jsonb,'aceptar idempotente aunque ya usado');
select throws_ok($$select public.accept_invitation('cccccccc-cccc-4ccc-8ccc-cccccccccccc',repeat('c',64))$$,'JT008',null,'aceptar misma clave otra huella');
select throws_ok($$select public.accept_invitation(gen_random_uuid()::text,repeat('b',64))$$,'JT101',null,'una cuenta activa no entra a otra pareja');
set local "request.jwt.claims" = '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","email":"sara@seed.test"}';
select throws_ok(format('select public.cancel_invitation(gen_random_uuid()::text,%L::uuid,2)',current_setting('tests.invitation')::jsonb->>'group_id'),'JT103',null,'no anula pareja ya activa');
select throws_ok(format('select public.regenerate_invitation(gen_random_uuid()::text,%L::uuid,2,repeat(''d'',64))',current_setting('tests.invitation')::jsonb->>'group_id'),'JT103',null,'no regenera pareja activa');
reset role;
select is((select count(*) from juntia_data.group_members where group_id=(current_setting('tests.invitation')::jsonb->>'group_id')::uuid and status='active'),2::bigint,'exactamente dos integrantes');
set constraints all immediate;
set constraints all deferred;
-- Crear para un correo fuera de la lista no consulta signup_allowlist (Q14).
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated","email":"diana@seed.test"}';
select set_config('tests.to_cancel',public.create_invitation('dddddddd-dddd-4ddd-8ddd-dddddddddddd','not-allowed@seed.test',repeat('d',64))::text,true);
select throws_ok(format('select public.cancel_invitation(gen_random_uuid()::text,%L::uuid,9)',current_setting('tests.to_cancel')::jsonb->>'group_id'),'JT011',null,'anular versión antigua falla');
select set_config('tests.cancelled',public.cancel_invitation('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',(current_setting('tests.to_cancel')::jsonb->>'group_id')::uuid,1)::text,true);
select is(public.cancel_invitation('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',(current_setting('tests.to_cancel')::jsonb->>'group_id')::uuid,1),current_setting('tests.cancelled')::jsonb,'cancelar misma clave recupera resultado con raíz ya invisible');
select throws_ok(format('select public.cancel_invitation(gen_random_uuid()::text,%L::uuid,2)',current_setting('tests.to_cancel')::jsonb->>'group_id'),'JT102',null,'nueva cancelación de descartada nunca da ok');
select throws_ok(format('select public.regenerate_invitation(gen_random_uuid()::text,%L::uuid,2,repeat(''e'',64))',current_setting('tests.to_cancel')::jsonb->>'group_id'),'JT102',null,'regenerar descartada nunca da ok');
select throws_ok(format('select public.cancel_invitation(''eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee'',%L::uuid,2)',current_setting('tests.to_cancel')::jsonb->>'group_id'),'JT008',null,'cancelar misma clave distinta versión');
reset role;
select is((select status from juntia_data.groups where id=(current_setting('tests.to_cancel')::jsonb->>'group_id')::uuid),'discarded','descarte confirmado');
select is((select count(*) from juntia_data.group_members where user_id='44444444-4444-4444-8444-444444444444' and status='active'),0::bigint,'membresía liberada');
-- Caducada y hash inválido: el mismo JT104 para todos los motivos del preview.
select tests.seed_couple('99999999-9999-4999-8999-999999999999','44444444-4444-4444-8444-444444444444');
update juntia_data.group_invitations set email='carla@seed.test',token_hash=repeat('9',64),created_at=now()-interval '8 days',expires_at=now()-interval '1 day'
where group_id='99999999-9999-4999-8999-999999999999';
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","email":"carla@seed.test"}';
select throws_ok($$select public.preview_invitation(repeat('9',64))$$,'JT104',null,'preview vencido');
select throws_ok($$select public.accept_invitation(gen_random_uuid()::text,repeat('9',64))$$,'JT104',null,'aceptación vencida');
select throws_ok($$select public.preview_invitation('malformed')$$,'JT104',null,'preview no distingue formato');
reset role;
-- Liberar la provisional de la fixture por el camino de la función.
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"44444444-4444-4444-8444-444444444444","role":"authenticated","email":"diana@seed.test"}';
select public.cancel_invitation(gen_random_uuid()::text,'99999999-9999-4999-8999-999999999999',1);
reset role;
-- Política rota: cada escritura debe fallar, nunca devolver un resultado de éxito sin completar idempotencia.
alter policy idempotency_complete on juntia_data.idempotency_records using(false);
set local role authenticated;
select throws_ok($$select public.create_invitation(gen_random_uuid()::text,'carla@seed.test',repeat('e',64))$$,'42501',null,'create_invitation comprueba row_count');
reset role;
alter policy idempotency_complete on juntia_data.idempotency_records using(actor_user_id=(select auth.uid()) and status='pending');
set local role authenticated;
select set_config('tests.policy_root',public.create_invitation(gen_random_uuid()::text,'carla@seed.test',repeat('f',64))::text,true);
reset role;
alter policy idempotency_complete on juntia_data.idempotency_records using(false);
set local role authenticated;
select throws_ok(format('select public.regenerate_invitation(gen_random_uuid()::text,%L::uuid,1,repeat(''e'',64))',current_setting('tests.policy_root')::jsonb->>'group_id'),'42501',null,'regenerate_invitation comprueba row_count');
select throws_ok(format('select public.cancel_invitation(gen_random_uuid()::text,%L::uuid,1)',current_setting('tests.policy_root')::jsonb->>'group_id'),'42501',null,'cancel_invitation comprueba row_count');
set local "request.jwt.claims" = '{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated","email":"carla@seed.test"}';
select throws_ok($$select public.accept_invitation(gen_random_uuid()::text,repeat('f',64))$$,'42501',null,'accept_invitation comprueba row_count');
reset role;
select is((select status from juntia_data.groups where id=(current_setting('tests.policy_root')::jsonb->>'group_id')::uuid),'provisional','las políticas rotas no dejan cambios parciales');
select * from finish();
rollback;
